  "challenge.definition.veil_cramped.reward.tier_2": "仓储上限 +50%",
  "challenge.definition.veil_cramped.reward.tier_3": "仓储上限 +70%",
  "challenge.definition.veil_cramped.rule": "全部有上限资源的仓储上限 −30% / −50% / −70%（科研点等无上限资源不受影响）。",
  "challenge.definition.veil_cramped.summary": "仓廪逼仄偏要开成繁盛市场，把有限空间用到极致。",
  "challenge.definition.veil_eternity_moment.name": "新难题",
  "challenge.definition.veil_eternity_moment.reward.tier_1": "永久飞升点获取 +10%；永久全产 +10%",
  "challenge.definition.veil_eternity_moment.reward.tier_2": "永久飞升点获取 +10%；永久全产 +20%",
  "challenge.definition.veil_eternity_moment.reward.tier_3": "永久飞升点获取 +10%；永久全产 +30%",
  "challenge.definition.veil_eternity_moment.rule": "科技与市政研究点成本、天壳厚度，以及掀起帘幕所需的飞升周期星屑门槛（基础 1000）均乘以本档倍率；尤里卡、前置条件和科技额外材料成本不变。",
  "challenge.definition.veil_eternity_moment.summary": "从破壳到掀幕的飞升需求，都会按档位提高五、十或二十倍。",
  "challenge.definition.veil_eternity_moment.tier_10": "十倍档",
  "challenge.definition.veil_eternity_moment.tier_20": "二十倍档",
  "challenge.definition.veil_eternity_moment.tier_5": "五倍档",
  "challenge.definition.veil_nofaith.name": "无神论",
  "challenge.definition.veil_nofaith.reward": "永久信仰产出 +50% · 信条抽选多一个候选（三选一变四选一）",
  "challenge.definition.veil_nofaith.rule": "全程不得装备任何信条；信仰的两条全产加成（局内存量档 + 跨局旧日信仰档）均失效。",
  "challenge.definition.veil_nofaith.summary": "弃绝一切信条与信仰之助，以无神之身抵达帘幕之后。",
  "challenge.definition.veil_one_way.name": "一往无前",
  "challenge.definition.veil_one_way.reward.tier_1": "永久仓储上限 +12%",
  "challenge.definition.veil_one_way.reward.tier_2": "永久仓储上限 +24%",
  "challenge.definition.veil_one_way.reward.tier_3": "永久仓储上限 +36%",
  "challenge.definition.veil_one_way.rule": "在 3/2/1 次合格轮回内掀起帘幕；第 3/2/1 次轮回后仍可在新周目完成飞升，超过次数上限则挑战失败。",
  "challenge.definition.veil_one_way.summary": "从新的飞升周期出发，在轮回次数耗尽前掀起帘幕。",
  "challenge.definition.veil_one_way.tier_1_rebirth": "一次轮回档",
  "challenge.definition.veil_one_way.tier_2_rebirths": "两次轮回档",
  "challenge.definition.veil_one_way.tier_3_rebirths": "三次轮回档",
  "challenge.definition.veil_rush.name": "飞升竞速",
  "challenge.definition.veil_rush.reward.tier_1": "永久星屑获取 +10%",
  "challenge.definition.veil_rush.reward.tier_2": "永久星屑获取 +20%",
  "challenge.definition.veil_rush.reward.tier_3": "永久星屑获取 +30%",
  "challenge.definition.veil_rush.rule": "从开始挑战起按现实时间计时，离线时间也计入；超时后本档不能领取竞速奖励。",
  "challenge.definition.veil_rush.summary": "在计时归零前研成《掀起帘幕》；退出游戏后计时仍继续。",
  "challenge.definition.veil_starve.name": "宇宙空洞",
  "challenge.definition.veil_starve.reward.tier_1": "每次飞升初始给 20 星屑",
  "challenge.definition.veil_starve.reward.tier_2": "每次飞升初始给 40 星屑",
  "challenge.definition.veil_starve.reward.tier_3": "每次飞升初始给 60 星屑",
  "challenge.definition.veil_starve.rule": "本轮破壳星屑结算收益降低，直至研成《掀起帘幕》。",
  "challenge.definition.veil_starve.summary": "星屑结算收益被压低，仍需一路研成《掀起帘幕》。",
  "challenge.definition.veil_temporal_pincer.name": "时间钳形攻势",
  "challenge.definition.veil_temporal_pincer.reward": "永久飞升点获取 +10%；通关后永久将失能逆时屋的激活资源消耗降至其基础建造资源的 1/10",
  "challenge.definition.veil_temporal_pincer.rule": "第一、二、三档开局分别获得 20、15、10 座失能逆时屋；人口上限建筑建造消耗分别 +200%、+400%、+600%；增加人口上限的政策卡不可用。",
  "challenge.definition.veil_temporal_pincer.summary": "开局拥有失能逆时屋，却要承受高昂的人口扩张成本。",
  "challenge.definition.veil_turmoil.name": "动荡年代",
  "challenge.definition.veil_turmoil.reward": "永久幸福度 +1",
  "challenge.definition.veil_turmoil.rule": "幸福度恒为最低档（动荡 ×0.80），奢侈品与奇观均无法抬升；直至研成《掀起帘幕》。",
  "challenge.definition.veil_turmoil.summary": "在最深的动荡里，依然把文明推向群星。",
  "challenge.definition.water_pollution.reward": "永久星屑产出 +10% · 商人奢侈品产出 +50% · 初始人口 +2",
  "challenge.definition.water_pollution.rule": "热液能建筑每秒排放与产出等值的污染（不计星屑树加成）；污染达 1000 / 4 万 / 16 万 / 640 万依次进入浊流、赤潮、死区、腐渊，逐级扣幸福、削藻食与珊瑚，并按秒掷死亡；每名死者永久提高幸福消耗（墓地限额内 0.3%、超限 3%）。",
  "challenge.definition.water_pollution.summary": "热液能产出即排污，五个阶段逐级侵蚀幸福、藻食与人口。",
  "challenge.definition.water_pollution.tier.label": "海渊澄明",
  "challenge.definition.weapon_critique.name": "武器的批判",
  "challenge.definition.weapon_critique.reward": "永久星屑获取 +10% · 战争行动军力消耗 -10%",
  "challenge.definition.weapon_critique.rule": "全程不得进行传播文化 / 传道信仰（软实力），也不得修建贸易路线；战争行动与吞并不受限制。",
  "challenge.definition.weapon_critique.summary": "以武力推进文明，拒绝文化与信仰的渗透，也拒绝商路贸易。",
  "challenge.definition.weapon_critique.tier.label": "以武止戈",
  "challenge.job_limit.reason": "忽视科文挑战限制：{jobName}已达 {cap} 人上限",
  "challenge.notice.abyss.progress": "{theologyStatus} · 剩余壳厚 {remainingShell}",
  "challenge.notice.abyss.rule": "全局产出 −{penaltyPercent}%",
