  "challenge.notice.eternity_moment.progress": "天壳 {shellProgress}/{shellTarget} · 星空探索 {starProgress}/{starTarget} · 太阳帆 {sailCount}/{sailCap} · 戴森节点 {nodeCount}/{nodeCap}",
  "challenge.notice.eternity_moment.rule": "研究成本 ×{multiplier} · 冰壳、星空、太阳帆、戴森节点目标 ×{multiplier}",
  "challenge.notice.good_old_days.government": "当前政体：{governmentName}",
