  "civic.data.cultural_heritage.name": "文化遗产",
  "civic.data.department.description": "解锁政体「王权制」（5 槽：礁栖核心建筑建造消耗 −10%），以及建筑「王国潮道」。书手更名为官员，市政点产出 +50%。",
  "civic.data.department.name": "行政部门",
  "civic.data.distributed_sov.description": "解锁政体「群星盟约」（9 槽，全产 +10%，幸福度 +1）；国家后缀改为群星盟约。",
  "civic.data.distributed_sov.name": "分布式主权",
