  "content.castle.building_upgrade_description": "每级降低所有建筑下一级造价，且效果递减；每级给{affectedEra}及之前有容量上限的资源增加{capacityBonus}容量，并使市政点产出增加{civicPointsPerSecondPerLevel}/级/秒。装备政策卡「{policyCardName}」时，每级额外增加{faithProductionBonus}信仰产出。",
