  "content.wonder_victory_monument.name": "胜利纪念碑",
  "content.wonder_voyager.description": "星际探测的起点：星空进度未满{thresholdPercent} 时每秒 {earlyExplorationRate}星空探索，满{thresholdPercent} 后转为每秒 {lateExplorationRate}且学者产出 {scholarBonus}。",
  "content.wonder_voyager.name": "旅行者1号",
  "domain.emperor.lv1.effect": "解锁奇观「{wonderName}」：消耗 {stoneBeamCost} 石梁。维持整个飞升，轮回后不会消失；书手固定改称「掌印者」，市政点产出 +{civicPercent}%。",
  "domain.emperor.lv1.text": "你们的灵能者在虚境中历经艰难探索，付出诸多代价，终于接近了虚境深处某位伟大存在的领域。\n无分上下左右的虚境中，突兀地显现出一座屹立于高峰之上的钢铁城堡，身披金色甲胄的卫队将之牢牢守卫。\n有威严之声在你们耳边响起，让你们不由得随那些金甲卫士一同跪下。\n不知为何，你们知道这声音来自祂，来自城堡的主人「煌皇」。\n「为何来此？为何不愿沉溺于轮回之终末，帝皇之幻梦？」",
  "domain.emperor.lv2.effect": "解锁奇观「{wonderName}」：消耗 {ironBracketCost} 铁制支架与 {steelPartCost} 钢制零件。维持整个飞升，轮回后不会消失；学者固定改称「持册人」，科技点产出 +{sciencePercent}%。",
  "domain.emperor.lv2.text": "你们的灵能者来到煌皇的领域。\n金甲的卫士首次引你们进入宫廷，觐见这位虚境神主。\n出乎意料的是，王座上坐着一个浑身脏污衣衫褴褛的老乞丐，枯瘦老朽的乞丐招招手，身旁近侍随之低头聆听。\n随后，近侍用你们之前听过的那个威严声音说道：\n「帝皇与乞丐，秩序与疯狂，又有何异？」",
  "domain.emperor.lv3.effect": "解锁奇观「{wonderName}」：消耗 {thetaFilmCost} θ金属自适应薄膜。维持整个飞升，轮回后不会消失；工艺效率 +{craftPercent}%。",
  "domain.emperor.lv3.text": "你们的灵能者来到煌皇的领域。\n你们随金甲卫士进入王庭，却见老乞丐已死，趴伏在王座边。此前的近侍从它身上拔出沾血的长剑，指向屏幕后的你。\n「既然龙蛇可变换，披甲可成圣，你我为何不可换位？」",
  "domain.emperor.name": "无信宫廷",
  "domain.lore.effect": "学者的科技点产出 +{scholarPercent}%，科技研究消耗 −{costSavePercent}%。",
  "domain.lore.lv1.text": "你们的灵能者在虚境中历经艰难探索，付出诸多代价，终于接近了虚境深处某位伟大存在的领域。\n自进入这个领域开始，就有一个声音在他们耳边滔滔不绝地诉说着宇宙的真理，而周边的虚境也不知何时变成了向前、向后、向上、向下皆无限延展的书架。\n随意抽出一些书籍，有的是稚童故事，有的是深奥知识，有的是家书情信，有的是历史秘辛，但更多的是用看不懂的语言写出的书本，甚至有的打开无一字，却会自动颂唱拗口的歌曲。\n但每一本的封皮上都有同一个名字「异叟」。\n「朝闻道，夕死可矣？」",
  "domain.lore.lv2.text": "你们的灵能者来到异叟的领域。\n依然是那个无边无际的大图书馆，而其主人也依旧隐没不现。\n结果也如上次一般，除少数意志坚定者与特地带来的盲目之人，绝大部分人都沉溺于知识之中，不愿回返。",
  "domain.lore.lv3.text": "你们的灵能者来到异叟的领域。\n书架倾倒，书籍散落，随意拾起任一本，里边的内容皆整齐划一：\n「你现在看到的这句话，也不过只是一串代码。」",
  "domain.lore.name": "知识回廊",
  "domain.pleasure.effect": "书手的市政点产出 +{scribePercent}%，市政研究消耗 −{costSavePercent}%。",
  "domain.pleasure.lv1.text": "你们的灵能者在虚境中历经艰难探索，付出诸多代价，终于接近了虚境深处某位伟大存在的领域。\n祂在此，又似乎在彼，所有灵能者都无法描绘出祂的具体形象，唯余抽象的「美」。随祂一同出现的，还有同样美不胜收的庭院光景——日光下的树荫，碧绿高拱的藤门，洁白石砖与彩绘玻璃，丝竹乐声与薄纱舞女……\n祂自称「堕殃」，是善，是恶，是高洁，是堕落，是纯洁无瑕之女神，是惑乱人心的妖姬，是胜利者的桂冠，是伊甸园的毒蛇。\n「你们有三人，而我的赐福只有两份，那么……」",
  "domain.pleasure.lv2.text": "你们的灵能者来到堕殃的领域。\n祂嬉笑着现身于欢愉之庭中，你们在无意识中纷纷倾倒，眼中光影变幻，如堕幻梦之中。\n再次清醒时，你们所有人都忘记了与祂说过什么，唯余祂的笑声还在耳边回荡。",
  "domain.pleasure.lv3.text": "你们的灵能者来到堕殃的领域。\n没有女神，没有妖姬，没有光辉灿烂的庭院，没有致人堕落的魔窟。\n只有一对眼眸挂于高空，祂的紫色眼眸，正盯着屏幕外的你。\n「如果你将这个窗口关闭，所有的美是否都无法存在？」",
  "domain.pleasure.name": "欢愉之庭",
  "domain.warlord.effect": "军人的军力产出 +{soldierPercent}%，每级要塞额外 +{fortressPercent}% 军人军力产出。",
  "domain.warlord.lv1.text": "你们的灵能者在虚境中历经艰难探索，付出诸多代价，终于接近了虚境深处某位伟大存在的领域。\n金铁交击声、旌旗摇动声、惨叫声、嘶鸣声、呐喊声一并在你们耳边响起——倏尔一切又归于寂静，披着鲜红大氅的庞然巨影自高处凝视着你们。\n祂自称「兵夔」，乃兵事之主，司掌战争、战略、战术，亦有勇气、兵击、武艺，且并不吝于向你们提供赐福。\n「代价？不需要代价，你们能来到这里，就已经在轮回中向我献上了数不尽的颅骨。」",
  "domain.warlord.lv2.text": "你们的灵能者来到兵夔的领域。\n军乐声、踏步声、号声、枪炮声、尖啸声一并在你们耳边响起，随后是惊天动地的巨响——倏尔一切又归于寂静，披着鲜红大氅的庞然巨影自高处凝视着你们。\n面对你们的恳求，祂只是点了点头，便转身离开了。",
  "domain.warlord.lv3.text": "你们的灵能者来到兵夔的领域。\n什么声音也没有，安静得不像是变幻莫测的虚境之中。\n祂抬头看向屏幕外的你。\n「如果一切都只是你的游戏，鲜血又是为何而流？」",
  "domain.warlord.name": "战争世界",
  "domain.wither.effect": "轮回点获取 +{yieldPercent}%，星屑获取 +{yieldPercent}%；飞升后起始获得 {startTide} 轮回点 + {startStardust} 星屑。",
  "domain.wither.lv1.text": "你们的灵能者在虚境中历经艰难探索，付出诸多代价，终于接近了虚境深处某位伟大存在的领域。\n不过阖眼之瞬，灵能者们的身体便在那存在的影响下变得枯槁老朽，却又在睁开眼睑之前重新变得丰盈。\n祂自称「枯荣」，又谦虚地自认为虚境的「园丁」。\n祂出乎所有人意料地亲切且和善，在与你们交流时，话语中竟似乎有着父母对子女期盼一般的情绪，并慷慨地向你们提供了赐福。\n「四季流转，生死轮回，文明兴衰，就如同圆石自山巅滚落，只会不断加速。」",
  "domain.wither.lv2.text": "你们的灵能者来到枯荣的领域，祂像是父母见到久未归家的孩子一样，饶有兴致地听着你们的讲述……\n「前往更遥远的星球？很不错。」\n你们的渴求……\n「你们理当获得嘉奖。」\n你们的疑惑……\n「不，不行，你们已经掀开了帷幕的一角，应该自己去寻找答案。」",
  "domain.wither.lv3.text": "你们的灵能者来到枯荣的领域，向祂提出了疑问。\n祂没有回答，只是转头看向了屏幕外的你。\n「你在看吗？应该在看吧？我能影响到帷幕后的你吗？」",
  "domain.wither.name": "生死间隙",
