  "tech.adiabatic.name": "绝热材料",
  "tech.adiabatic.unlock_desc": "欧罗巴冰面发射场可切换制造太阳帆（每级每秒耗铀{sailUraniumRate}、强工质火箭引擎{sailEngineRate}、θ金属自适应薄膜{sailFilmRate}、热液能{sailHydrothermalRate}）或戴森球节点（每级每秒耗铀{nodeUraniumRate}、强工质火箭引擎{nodeEngineRate}、θ金属自适应薄膜{nodeFilmRate}、钛合金板{titaniumPlateRate}、热液能{nodeHydrothermalRate}）。星图开启戴森球终局面板：太阳帆{solarSailGoal}+ 戴森球节点{dysonNodeGoal}即通关。",
  "tech.alien_eng.name": "大型异星工程",
  "tech.alien_eng.unlock_desc": "建筑：马尔斯工造中心（造价{biomaterialCost}θ生物金属 {engineCost}强工质火箭引擎，每级产钛与钛金板件）。",
  "tech.ancient.effect_desc": "所有太空建筑建造消耗 {effectPercent1}（多个减免源乘法叠加，合计至多 {maximumReduction}）。星屑跨周目累计，在周目结算时发放。",
  "tech.ancient.name": "超古代科技",
  "tech.apprentice.name": "学徒制",
  "tech.apprentice.unlock_desc": "解锁砂矿坑升级「鱼骨矿井」；购买后矿工金属产出 {effectPercent1}、伴生暖石 {effectPercent2}。",
  "tech.architect.name": "大型架构",
  "tech.architect.unlock_desc": "解锁工坊升级「物流仓库」：商队驿站升级后更名，每级给纪元{eraCount}及之前解锁的有上限材料 {capacityPerLevel}容量。",
  "tech.autodrill.unlock_desc": "解锁工坊升级「自动化钻探」：按开启矿井比例提高钛、铀产出，每座耗{hydrothermalRate}热液能/秒；矿工开始伴生采出铀。",
  "tech.ballistics.name": "弹道学",
  "tech.ballistics.unlock_desc": "解锁工坊升级「金属弹丸」（战争行动对敌国规模损耗 +30%）。",
  "tech.banking.name": "银行业",
  "tech.banking.note": "Civ VI: Banking · 贸易区{zoneLevel}级，账本才比货值钱。",
  "tech.beyond_veil.name": "掀起帘幕",
  "tech.beyond_veil.unlock_desc": "学成即可在底栏「掀起帘幕」：结算本帷幕周期的飞升点，清空轮回点与星屑，带着飞升点从 ERA1 重开。",
  "tech.bigdata.name": "大数据",
  "tech.bigdata.unlock_desc": "解锁礁栖核心自动建造（建筑页的自动升级开关对该区生效）。",
  "tech.biomat.name": "生物材料",
  "tech.biomat.unlock_desc": "解锁建筑「生物材料研究所」（制造 θ生物金属）与工坊升级「θ生物金属工具三件套」。",
  "tech.blackhistory.name": "黑历史蓝图",
  "tech.blackhistory.unlock_desc": "工艺效率 {effectPercent1}（折进工坊工艺制作效率基数）。",
  "tech.blacksmoker.name": "黑烟囱炼铁",
  "tech.blacksmoker.note": "黑烟囱（海底热液喷口）的炽热矿浆富含铁硫，经富集提纯后炼铁更出铁。精铁产出{outputMultiplier}（与「铁器」乘法叠加）。",
  "tech.bronze.name": "青铜术",
  "tech.bronze.note": "解锁工坊：珊瑚→骨材、矿砂→精铁两条加工线的物理前提。",
  "tech.calendar.effect_desc": "信息奖励：显示海底火山的周期阶段与读数；不影响资源产出。",
