  "tech.canfill.name": "装罐填埋",
  "tech.canfill.note": "把废气封进旧罐子埋回海床：汽轮机额外耗{metalPerSecond}金属/秒/级，该类污染源 {effectPercent1}。",
  "tech.castle.unlock_desc": "解锁议事厅升级「城堡」；购买后降低建筑造价，每级为纪元{eraCount}及之前有上限资源 {capacityPerLevel}容量、市政点 {civicRate}。",
