  "tech.exostruct.name": "壳外建筑",
  "tech.exostruct.unlock_desc": "解锁「星空观测站」升级和深空探测功能；购买升级后科技产出 {effectPercent1}、每秒增加{explorationRate}星空探索，并消耗热液能（可开关）。",
