  "tech.gravity_sling.name": "引力弹弓",
  "tech.gravity_sling.unlock_desc": "奇观「朱庇特质量加速站」（消耗{engineCost}强工质火箭引擎 {filmCost}θ金属自适应薄膜）：每秒耗{hydrothermalRate}热液能，生物材料研究所产出 {effectPercent1}。",
  "tech.heir_of_stars.name": "继承繁星之人",
