  "tech.highthermo.name": "高压热机",
  "tech.highthermo.unlock_desc": "解锁工坊升级「热回收改造」「废钢锻造」和奇观「高压热机管道」；奇观提供热液能 {hydrothermalSupply}。",
  "tech.horsemanship.name": "马术",
