  "tech.metalrefine.name": "金属精炼",
  "tech.metalrefine.note": "Civ VI: Metalurgy · 完成鱼骨矿井即掌握。解锁热液汽轮机 / 热液工坊 / 潮汐往复机 / 自动工坊 / 钢制零件。",
  "tech.metalrefine.unlock_desc": "解锁工坊配方「钢制零件」。",
  "tech.microwave_heat.name": "超远距微波加热",
  "tech.microwave_heat.unlock_desc": "建筑：欧罗巴冰面发射场（每座独立按制造周期计时，默认{cycleSeconds}s；周期完成时按本场等级同时发射太阳帆。太阳帆模式每级每秒耗{uraniumRate}铀 {engineRate}强工质火箭引擎 {filmRate}θ金属自适应薄膜 {hydrothermalRate}热液能）。星图每个太阳帆 {sailHydrothermalRate}热液能/秒。",
  "tech.mining.name": "采矿",
  "tech.mining.note": "解锁矿工与砂矿坑：矿工产金属、伴生暖石（保温法开关的燃料）；砂矿坑把金属产出再提{effectPercent1}。",
  "tech.minipump.name": "热液泵小型化",
  "tech.minipump.unlock_desc": "解锁工坊配方「钛金板件」（{titaniumPerBatch}钛制成{plateCount}个），以及扩容升级「合金仓储」。",
  "tech.modpart.name": "可替换部件",
  "tech.modpart.note": "解锁工坊区自动建造。",
  "tech.modpart.unlock_desc": "解锁工坊区自动建造。",
  "tech.modtrans.name": "现代化交通",
  "tech.modtrans.unlock_desc": "解锁奇观「总物流站」；建成后王国潮道每级提供 {craftingBonus} 工艺效率。若同时建成「全国快速物流通道」，该通道的精铁/钢产能加成翻倍。",
  "tech.mwconverge.effect_desc": "每级使太阳帆热液能产出 {effectPercent1}，最高{maxLevel}级；研究成本每级{costMultiplier}。",
  "tech.mwconverge.name": "微波收敛研究",
  "tech.mwconverge.unlock_desc": "一张科技卡可研究{maxResearches}次，每级使太阳帆热液能产出 {effectPercent1}。",
  "tech.name.castle": "城堡",
  "tech.nanotech.name": "纳米技术",
  "tech.nanotech.unlock_desc": "解锁工艺「θ金属自适应薄膜」（{thetaMetalPerBatch}θ →{plateCount}钛金板件）。生物材料研究所产出 {effectPercent1}、效率 {effectPercent2}。",
  "tech.navigation.name": "导航",
  "tech.navigation.note": "Civ VI: Sailing 位 · 光落在远处的礁石上，才知道那边有什么。",
  "tech.near_star_orbit.name": "近恒星轨道建设",
  "tech.near_star_orbit.unlock_desc": "建筑「太阳星环」（消耗{biomaterialCost}θ金属 {kelpBinCost}封闭藻仓）：每秒产{biomaterialRate}θ金属/级，人口上限 {populationPerLevel}/级。",
  "tech.nuclear_fusion.name": "核聚变",
  "tech.nuclear_fusion.unlock_desc": "核热厂：铀消耗{uraniumMultiplier}、热液能产出{hydrothermalMultiplier}。",
  "tech.physics.name": "物理",
  "tech.physics.unlock_desc": "解锁工坊配方「脚手架」和砂矿坑升级「深层矿井」（矿工开始伴生钛）。",
  "tech.plant.name": "种植",
  "tech.plant.note": "采集者 → 农民，藻食产出 {effectPercent1}，并解锁海藻仓。同一个人换了身份，不是新职业。",
  "tech.prerequisites.blocked": "缺少前置科技：{technologyNames}",
  "tech.printing.name": "印刷术",
  "tech.printing.note": "Civ VI: Printing · 热液工坊{workshopLevel}级开版。字能印了，珊瑚也能催了。",
  "tech.protoai.name": "初级人工智能",
  "tech.protoai.unlock_desc": "解锁建筑「机器人充能站」（维持 {robotPopulation} 机器人人口/级：仅担任非书手/学者岗位，产出 +{robotOutputBonus}、不影响信仰点）；解锁工坊升级「全水文军事辅助机械」（战争行动敌国规模损耗 +70%）。",
  "tech.pubedu.name": "普及教育",
  "tech.pubedu.note": "Civ VI: Public Schooling · 科学产出达到{researchRate}/s。解锁学校（每名鲛人 {researchPerPerson}科技/秒、{civicPerPerson}市政/秒，每级）。",
  "tech.quarry.name": "采石",
  "tech.quarry.note": "采石工产「石头」。cond 用珊瑚存量而不是时间：玩家攒够了自然会去凿石头， * 这也是石头这条线第一次在树上露面（它后面要养石屋）。",
  "tech.refine.effect_desc": "生产精铁和钢时，暖石消耗 {effectPercent1}。",
