  "tech.robotics.name": "机器人技术",
  "tech.robotics.unlock_desc": "解锁工坊升级「工业机器人」（每座运行工坊对应的工艺产出份额 {effectPercent1}，总加成按运行工坊占比计算；每座运行工坊耗{hydrothermalRate}热液能/秒）。人造卫星星空探索 {satelliteExplorationBonus}（永久）。",
  "tech.rocket.name": "火箭研究",
  "tech.rocket.unlock_desc": "解锁科研区自动建造与太空建筑「轨道卫星」。",
  "tech.scaffold_t.name": "构架术",
  "tech.scaffold_t.unlock_desc": "解锁工坊配方「绳」。",
  "tech.scholar_t.name": "书写",
  "tech.scholar_t.note": "潮纹馆（原「聆听巢」）的解锁项 + 学者产出 {effectPercent1}。层三。",
  "tech.sealbin.name": "密闭水仓",
  "tech.sealbin.unlock_desc": "解锁工坊配方「封闭藻仓」和工坊升级「温水藻场」；购买升级后，每级藻场额外提供 {researchRate}科技点/秒，且不受季节影响。",
  "tech.shellgeo.name": "天壳地质学",
