  "tech.siegeT.name": "攻城学",
  "tech.siegeT.unlock_desc": "解锁工坊升级「回旋迸石机」（战争行动对敌国规模损耗 +10%）。",
  "tech.skydrill.name": "天穹钻机",
  "tech.skydrill.unlock_desc": "解锁奇观「天穹钻机」。",
  "tech.spacestation.name": "空间站",
