  "tech.starfrontier.unlock_desc": "解锁奇观：现实透孔仪。（成本待标定）",
  "tech.strong_ai.name": "强人工智能",
  "tech.strong_ai.unlock_desc": "工坊升级「强人工智能」（消耗{biomaterialCost}θ金属）：机器人产出{previousMultiplier}→{newMultiplier}，且机器人按人口数量产出信仰。",
  "tech.study.eureka_required": "尤里卡未达成：达成条件后才能研究",
