  "tech.study.status.mastered": "已掌握",
  "tech.supercrit.name": "超临界致密材料",
  "tech.supercrit.unlock_desc": "解锁大陆板块加固构件奇观与工坊升级「地壳钻井」。",
  "tech.surface.name": "地表探测",
  "tech.surface.unlock_desc": "解锁奇观「摇篮」：建成后矿线全产出 {effectPercent1}。",
  "tech.survive.description": "采集 · 抗寒 · 住房 · 破壳",
  "tech.survive.name": "生存",
  "tech.terraform.name": "星球改造",
  "tech.terraform.unlock_desc": "可启动泰拉星球改造（需先启动星球重构机 G.E.E.K）。泰拉改造{terraformTime} 完成后，人口/速生珊瑚林/矿井/生息区建筑升级消耗回到{levelThreshold}级之前。",
  "tech.thermal.name": "保温法",
  "tech.thermal.note": "解锁暖石开关：寒流季启用后消耗暖石，抵消部分季节减产并免除冻伤。",
  "tech.thermo.name": "热力学",
  "tech.thermo.unlock_desc": "解锁工坊升级「高压气泵」；购买后热液汽轮机的热液能产出 {effectPercent1}。",
  "tech.tiddivine.name": "海潮占卜",
  "tech.tiddivine.note": "比裸季更窄：海底火山的周期波动被读得更死（活跃更旺、休眠更枯），是唯一的季节收窄来源。",
  "tech.unified_field.name": "大统一方程",
  "tech.unified_field.unlock_desc": "按当前科技点 + 市政点给予全产加成（与旧日信仰同式：每高一个数量级 {bonusPerMagnitude}），作用于除科技、市政、信仰之外的全部产出。",
  "tech.vector_ctrl.name": "空间矢量控制",
  "tech.vector_ctrl.unlock_desc": "发射场制造时间减少{timeReduction}（太阳帆与戴森球节点的产出节律{previousCycle} →{newCycle}）。",
  "tech.ventrecir.effect_desc": "热泉炉（金属+暖石 → 精铁）与热液工坊（金属 → 钢）的原料消耗{inputMultiplier}（{inputReduction}）；只省原料，产能不变。",
  "tech.ventrecir.name": "热泉回流",
  "tech.ventrecir.note": "更深热泉的循环工艺：热泉炉省金属+暖石、热液工坊省金属，各{inputMultiplier}（{inputReduction}）＝同产出只耗六成原料，产能不变。",
  "tech.winter.name": "严冬计划",
  "tech.winter.unlock_desc": "解锁泰拉地壳密闭水舱巨构（每级 {populationPerLevel}人口上限，消耗{hydrothermalRate}热液能/秒）。",
  "tech.writing.name": "结绳",
  "tech.writing.note": "{researchCost}科研点但需手动研究：建成第{kelpFarmCount}座深海藻场即揭示并开放研究，玩家点一下才掌握、解锁学者。层一开门节点。",
  "tech.xenoconst.name": "异星建筑工程",
  "tech.xenoconst.unlock_desc": "解锁建筑「瑞亚星矿井」（星海区在地开采）。",
