  "ui.challenge.result.failed_rebirth_limit": "挑战未通关：{challengeName} · {tierName} 已完成 {rebirthCount} 次合格轮回，超过 {rebirthLimit} 次上限；本档奖励未领取，可重新开始本档。",
  "ui.challenge.result.failed_time": "挑战未通关：{challengeName} · {tierName}超过时限 {timeLimit}（本次用时 {elapsedTime}）。本档奖励未领取，重开本周目后可重试。",
  "ui.challenge.result.final_restriction": "成绩已定格；限制生效中，解除后不可再打开。",
  "ui.challenge.result.prestige_bonus": "挑战通关永久加成：轮回点获取 +{prestigePointBonus}",
  "ui.challenge.result.repeated_clear": "再次通关：{challengeName} · {tierName}。重复挑战不再发放永久奖励，本局成绩已计入排行榜。",
  "ui.challenge.result.reward_applied": "永久奖励已生效：{reward}",
  "ui.challenge.result.time_limit": "本档挑战用时 {elapsedTime}，超过时限 {timeLimit}，奖励未领取。",
  "ui.challenge.reward.permanent": "永久奖励",
  "ui.challenge.reward.tier": "本档奖励：{rewardDescription}",
  "ui.challenge.rule.cold_season_active": "寒流季：保温法禁用，产业仍可消耗暖石",
  "ui.challenge.rule.cold_season_inactive": "非寒流季：保温法可正常使用",
  "ui.challenge.rule.science": "学者与{scribeName}岗位人数各不得超过本档上限",
  "ui.challenge.run.must_finish": "先完成或重开当前挑战周目。",
  "ui.challenge.run.released": "已解除",
  "ui.challenge.run.restrictions": "本轮限制",
  "ui.challenge.run.reward_on_completion": "本轮限制生效中。通关后领取当前档奖励。",
  "ui.challenge.start.confirm.ascension_cycle_ready": "本飞升周期已达到掀起帘幕的门槛。开始挑战时会自动掀起帘幕并结算，预计获得 <b>{ascensionPointPayout} 飞升点</b>。",
  "ui.challenge.start.confirm.ascension_cycle_reset_notice": "当前周目、轮回点、星屑、天赋和旧日遗产将重置；已完成挑战、永久奖励与已解锁的飞升路径保留。",
  "ui.challenge.start.confirm.ascension_cycle_unready": "本飞升周期尚未达到掀起帘幕的门槛。开始挑战时不会结算飞升点，但仍会清空本周期并开启新周期。",
  "ui.challenge.start.confirm.button.replay": "再次挑战",
  "ui.challenge.start.confirm.button.settle_and_start": "结算并开始",
  "ui.challenge.start.confirm.button.start_ascension": "开始飞升挑战",
  "ui.challenge.start.confirm.current_run_notice": "当前周目将自动结算并重开。",
  "ui.challenge.start.confirm.estimated_prestige_reward": "预计获得 <b>{prestigePointPayout} 轮回点</b>。",
  "ui.challenge.start.confirm.replay_notice": "本次为重复挑战：通关不再发放永久奖励，也不会再次提高轮回点获取，只刷新排行榜成绩。",
  "ui.challenge.start.confirm.replay_tag": "· 重复挑战",
  "ui.challenge.start.confirm.reset_notice": "本局进度会重置；轮回点、已完成挑战与永久奖励保留。",
  "ui.challenge.start.confirm.theology_required": "尚未完成《神学》，本次不会获得轮回点。",
