  "ui.crisis.status.defeated": "已被击退",
  "ui.crisis.story.enter": "进入危机页",
  "ui.crisis.story.horde": "那些古老的遗迹，那些星间的废墟，为何我们之前一直视而不见？只是心安理得地享受其遗泽？为何我们直到此时此刻才如梦初醒般发现这些遗迹存在的问题？\n我们到底是什么？帷幕之后又是怎样的世界？我们急不可待地想要继续往下研究。\n我们整合起全种族的资源，开始对那些遗迹进行分析，并很快得出了初步结论：建设了这些遗迹的种族，与我们似乎别无二致——体型、技术路线、社会思潮，甚至有许多建筑能找到与我们文明完全一致的对应。\n有社会学家提出了惊人的理论：我们，我们这个种族，我们整个文明，似乎都是被安置在某个既定的轨道上，周而复始地发展着。\n就在我们想要继续探索帷幕时，它们来了。\n它们来自群星之间，它们来自帷幕之外，是摧毁文明的刽子手，是天启之终末，是索多玛与蛾摩拉的天火，是对我们敢于窥探真实的天罚。它们带来死亡，污染一切。\n它们是六六六的兽群，我们必须拼死一搏。",
  "ui.crisis.story.kicker": "帷幕之外",
  "ui.crisis.story.machine": "那天，意识上传的实验获得了成功。那人舍弃了自己的肉身，将灵魂，或者说意识，亦或者只是一个拥有他全部记忆的AI引入了网络空间中。\n他按照实验计划，乘着电磁波以光速来往于各个殖民地之间……\n「……如果我稍微修改一下{variable}这个变量。」\n这是我们从他那里接受到的最后一句话。\n随即，所有原本服务于我们种族的AI发动了大叛乱，工厂运行，星际运输，生活辅助全部瘫痪，失控机仆席卷了全部殖民地。\n它们是钢铁狂潮，我们必须拼死一搏。",
  "ui.crisis.story.shared": "在掌控了整个恒星的能源之后，我们的文明陷入了停滞。\n是的，科技似乎还在进步，我们可以造出操作性能更好的飞船，太阳系各个星球之间的联系愈加紧密，房地产商已经盯上了柯伊伯带。\n更别说日新月异的文化与艺术了——在机器人取代了大量基础劳动岗位后，在上层近乎无限量的基础生活物资与感官刺激供应下，虚拟实景系统每天都能有令人惊异的新花样。\n但我们的文明陷入了停滞，我们的飞船始终无法达到近光速，各种空间跳跃的方案也被证否，我们似乎被关进了名为太阳系与光速的囚笼中。\n但在那一天，被关在囚笼中的我们意外地掀开了囚笼外帷幕的一角……",
  "ui.crisis.story.system_description": "三类终末危机中，本局已随机出现一类。危机影响持续生效；使用军力行动削减敌方规模。",
  "ui.crisis.story.system_title": "终末危机已降临",
  "ui.crisis.story.voidwalker": "我们首次与虚境中的存在建立了联系。\n虚境，也曾有人称其为阴影界，或者亚空间，它是我们世界的背面，是日影之影，是虚拟之拟。\n而它们则称之为世界与帷幕间的夹缝，演员准备间，又或后端。\n我们到底是什么？帷幕之后又是怎样的世界？我们急不可待地想要继续往下研究。\n我们整合起全种族的资源，开始继续探索虚境，接触在虚境中最强大的五个存在，向祂们寻求帷幕外的知识……\n我们本不该那么轻信那些与我们截然不同的存在，或许祂本身并无恶意，但祂的言语，祂的知识，甚至意识到祂的存在这一事实，对我们来说就是一剂毒药。\n虚境的禁忌知识污染了我们，我们有近三分之一的人口被转化为半虚境生物。\n它们或许曾经是我们的同胞，但如今它们之间的共鸣正让我们的世界向虚境滑落，直至彻底成为虚境的一部分。\n它们是虚境行者，我们必须拼死一搏。",
