  "ui.faith.global_bonus.basis_tag": "按存量",
  "ui.faith.global_bonus.explanation": "按信仰存量的数量级提供全产出加成：{bonusExamples}。每增加一个数量级，加成提高{bonusPerMagnitude}。此加成影响{affectedResources}等全部资源，但不影响信仰本身（避免正反馈）。",
  "ui.faith.global_bonus.title": "全产加成",
  "ui.faith.locked.overview": "信仰是第三条文明发展支柱：人口越多，信仰积累越快；信仰存量越高，全产加成越强。",
  "ui.faith.locked.title": "信仰页未开启",
  "ui.faith.locked.unlock_note": "完成「{unlockCivicName}」后开启此页；它是{unlockEra}的关键节点之一。在那之前，信仰也不会显示在顶栏。",
  "ui.faith.name.anchor_badge": "◈ 虚境锚定",
  "ui.faith.name.empty_editable": "尚未命名。请在上方输入框设定名称；之后可随时免费修改，此名称会显示在顶栏信仰资源格。",
