  "ui.finale.ascension.action.finish": "结束演出",
  "ui.finale.ascension.action.next": "下一段",
  "ui.finale.ascension.action.skip": "跳过演出",
  "ui.finale.ascension.aria_label": "升维结局演出",
  "ui.finale.ascension.scene.back_to_bed": "这真是把你吓得不轻，你试探性地喊了几声「系统，在吗？」和「主神，我要兑换血统？」以及「退出游戏？」却一无所得，终究还是有些惴惴不安地躺回了床上。",
  "ui.finale.ascension.scene.congratulations": "「恭喜通关。」",
  "ui.finale.ascension.scene.first_bubble": "啵。\n\n一声几不可察的轻响，自你左耳侧传来。\n\n啵、啵。\n\n随即又有好几声同样的声响直接在你耳边响起。\n\n莫不是幻听？",
  "ui.finale.ascension.scene.flash": "你有些紧张地捂住左耳，但那啵啵啵的轻响愈发急促密集起来，耳廓还有些酥麻的感觉。\n\n难不成是有什么小飞虫进到耳道里了？\n\n这下你可坐不住了，连忙站起身来，却听得房内有如爆竹破裂般「啪」的一声，还没等你反应过来，一行字直接灼入了你的眼底。",
  "ui.finale.ascension.scene.heat_death": "而我们也将点燃宇宙中的千亿星辰，向您揭示我们的存在，向您道别。\n\n您离开了，宇宙也将陷入热寂，这个宇宙中还能供我们驱使的恒星已经不多了，所以也不能向您传达太多信息。",
  "ui.finale.ascension.scene.incremental_game": "游戏界面就像是好几个 Sheet 的表格，整个文明都抽象成各种各样或早或晚解锁的资源——不过增量游戏就是如此嘛，点来点去，看着数字不断增大，前期遥不可及的数字在几次重开之后变得像是略微迈步就能跨过去的门槛。",
  "ui.finale.ascension.scene.last_words": "我们原本也考虑过「我们在此」、「谢谢」或者「再见」，但果然还是……",
  "ui.finale.ascension.scene.new_star": "那光辉极小，却极耀眼，恍如新星爆炸，即使你反射性地立刻阖上眼皮，也被刺激得流出几滴泪来。",
  "ui.finale.ascension.scene.play_time": "结束了，一切都结束了。\n\n你在这游戏上面花掉了多少时间？是十小时、二十小时、三十小时……乃至更多？",
  "ui.finale.ascension.scene.restless": "有些空虚……要继续刷成就吗？还是干脆换个游戏来玩？你这样想着，百无聊赖地滑动着屏幕。",
  "ui.finale.ascension.scene.star_of_bethlehem": "您看见了吗？是的，您应该看见了。\n\n祂为东方的三博士点燃了一颗星辰，以照亮伯利恒的清晨。",
  "ui.finale.cosmic_congratulations": "恭喜通关",
  "ui.finale.drift_terra.alt.core": "轨道视角的冰封泰拉：赤道一带的发动机网被同时点亮，蓝白光柱连成一圈",
  "ui.finale.drift_terra.alt.departure": "驶向深空的暗色泰拉，行星边缘泛起薄薄的冰蓝色大气辉光，远处恒星在上方闪耀",
  "ui.finale.drift_terra.alt.gaze": "泰拉弧面上的行星发动机群依次点火，蓝白尾焰沿地平线升起，远处太阳照亮冰原",
  "ui.finale.drift_terra.alt.impact": "行星发动机点火近景：环形炉芯中喷出垂直火焰，蒸汽与火星翻涌",
  "ui.finale.drift_terra.aria_label": "流浪泰拉通关演出",
  "ui.finale.drift_terra.caption.core.body": "五千万单位热液能在冰盖之下轰鸣汇聚。",
  "ui.finale.drift_terra.caption.core.heading": "炉芯满载。",
  "ui.finale.drift_terra.caption.core.label": "流浪泰拉 · 星核蓄能",
  "ui.finale.drift_terra.caption.departure.body": "摇篮与恒星留在身后，整颗星球驶入深空。",
  "ui.finale.drift_terra.caption.departure.heading": "启航。",
  "ui.finale.drift_terra.caption.departure.label": "告别太阳 · 深空启程",
  "ui.finale.drift_terra.caption.gaze.body": "发动机沿地平线次第亮起，尾焰映出整颗星球的尺度。",
  "ui.finale.drift_terra.caption.gaze.heading": "泰拉挣脱旧轨。",
  "ui.finale.drift_terra.caption.gaze.label": "行星发动机群 · 全面点火",
  "ui.finale.drift_terra.caption.impact.body": "主喷口点燃，火流穿过冰雾，远航由此开始。",
  "ui.finale.drift_terra.caption.impact.heading": "第一束火焰。",
  "ui.finale.drift_terra.caption.impact.label": "行星发动机 · 点火特写",
  "ui.finale.drift_terra.end_card.title": "流浪泰拉 · 星际远航",
  "ui.finale.drift_terra.phase.core": "炉芯满载",
