  "ui.finale.verge.alt.ending": "戴森球文明消失在紫色视界之后，信号延伸向另一重宇宙",
  "ui.finale.verge.alt.gaze": "母星和破碎星环坠入黑洞，旧现实的边界正在崩解",
  "ui.finale.verge.alt.impact": "引力将戴森球结构、舰队与母星卷向事件视界",
  "ui.finale.verge.alt.intro": "紫色黑洞在戴森球中心形成，像一道通往虚境的裂隙",
  "ui.finale.verge.aria_label": "飞升虚境终局演出",
  "ui.finale.verge.caption.1.body": "戴森球聚起的恒星伟力，正将时空撕开一道裂口。",
  "ui.finale.verge.caption.1.heading": "现实开始松动。",
