  "ui.intro.achievements.description": "文明里程碑收藏墙。",
  "ui.intro.achievements.title": "这是什么 · 成就",
  "ui.intro.challenges.description": "给周目附加全局规则的自限玩法：禁保温、压人口、限岗位、限时间等，规则越难，通关后给的永久奖励越强。",
  "ui.intro.challenges.title": "这是什么 · 挑战",
  "ui.intro.civic.description": "按纪元推进的市政树，用于解锁建筑、政体与政策卡。",
  "ui.intro.civic.step": "1. 不同政体拥有各自的被动效果与政策槽数量，越后期的政体槽位越多。<br>2. 政策卡必须装入政策槽中才会生效。",
  "ui.intro.civic.title": "这是什么 · 市政",
  "ui.intro.company.description": "由纪元 {eraNumber} 市政《宏观经济学》解锁：系统会自动成立藻食与珊瑚两家公司，随时间从乡镇成长为地方、全国乃至星际巨头，提高对应产出，同时恒增 {luxuryConsumptionIncreasePercent} 奢侈品消耗。",
  "ui.intro.company.title": "这是什么 · 公司",
  "ui.intro.diplomacy.description": "完成《导航》科技后开放，与其他国家进行交流。",
  "ui.intro.diplomacy.step": "1. 用<b>劫掠 / 入侵 / 全面战争</b>削减敌国规模，行动消耗<b>军力储备</b>，军人可能阵亡。<br>2. 规模归零即可<b>吞并</b>；敌国也会反过来入侵，被攻入会损失材料、人口或建筑等级。",
  "ui.intro.diplomacy.title": "这是什么 · 外交",
  "ui.intro.faith.description": "完成《神学》市政后开启，以信仰驱动宗教加成与教义抉择。",
  "ui.intro.faith.step": "1. 每局积累的信仰会在轮回后沉淀为「旧日信仰」，在后续周目持续生效。<br>2. 研究《神学》并建立宗教后，轮回结算即可获得轮回点。",
  "ui.intro.faith.title": "这是什么 · 信仰",
  "ui.intro.folk.description": "管理族民人口与职业分配：族民消耗藻食、需要住房，分配为采集者、采石工、学者等岗位后驱动各项产出。",
  "ui.intro.folk.step": "人口顶到上限就建更多住房，藻食必须超过{kelpThreshold}才会有新增人口。",
  "ui.intro.folk.title": "这是什么 · 族民",
  "ui.intro.help.tooltip": "这是什么？",
  "ui.intro.meta.description": "跨周目永久成长：结算获得的轮回点可在此换取永久加成，后续周目一律生效。",
  "ui.intro.meta.step": "解锁神学后才能获得轮回点，破壳后才会获得星屑。",
  "ui.intro.meta.title": "这是什么 · 轮回商店",
  "ui.intro.star_dome.description": "跨周目星际成长：轮回结算时根据太空与异星设施、星空探索及戴森球进度发放星屑，可换取永久强化，也可与轮回点按固定汇率互换。",
  "ui.intro.star_dome.step": "建成首座轨道卫星即可永久解锁本页；之后即使进入新周目、卫星等级归零，商店仍保持开放。星屑在合格轮回结算时入账。",
  "ui.intro.star_dome.title": "这是什么 · 星屑商店",
  "ui.intro.star_map.description": "破壳后解锁的星空探索视图，前期为母星所在行星系，后期会解锁恒星系界面。",
  "ui.intro.star_map.step": "这里的建筑和巢穴标签下星海区建筑是一致的。",
  "ui.intro.star_map.title": "这是什么 · 星图",
  "ui.intro.tech.description": "按纪元推进的科技树，用于解锁新建筑、资源产线与后续系统。",
  "ui.intro.tech.step": "1. 科技起初处于隐藏状态，达成尤里卡条件后会显现详情并开放研究。<br>2. 完成当前纪元的关键节点后，下一纪元科技的尤里卡会提前显露，方便提早布局。",
  "ui.intro.tech.title": "这是什么 · 科技",
  "ui.intro.village.description": "鲛人国度所有已经解锁的建筑列表，你可以在这里对其进行升级。",
  "ui.intro.village.step": "使用手动「采藻食」、「采珊瑚」攒够资源，建起深海藻场，礁口巢。",
  "ui.intro.village.title": "这是什么 · 巢穴",
  "ui.intro.wonder.description": "大型工程项目：耗巨量资源建成，给全局强增益或解锁终局机制（如天穹钻机）。",
  "ui.intro.wonder.title": "这是什么 · 奇观",
  "ui.intro.workshop.description": "将原料加工成进阶物资（如石梁、硬珊瑚等），并可配置自动制造槽位。",
  "ui.intro.workshop.step": "工艺效率越高，消耗同样材料获得的进阶物资就越多；工具与永久升级请在「工坊升级」页签购买。",
  "ui.intro.workshop.title": "这是什么 · 工坊制造",
  "ui.intro.workshop_upgrades.description": "购买职业工具与永久性工艺升级，一次性投入即可在本局长期生效。",
  "ui.intro.workshop_upgrades.step": "已完成的项目可通过右上角开关隐藏，尚未看过的升级项会标记为 NEW。",
  "ui.intro.workshop_upgrades.title": "这是什么 · 工坊升级",
